function __tpOverlay(html){const root=document.createElement("div");root.className="tpOtpOverlay";root.innerHTML=html;document.body.appendChild(root);return root}

window.__tpAskDriverVehicle = function (vehicles, lastId) {
  return new Promise((resolve) => {
    const list = (vehicles || []).filter((v) => v && v.id);
    const root = __tpOverlay(
      '<div class="tpOtpCard tpDoneCard" role="dialog" aria-modal="true">' +
        '<div class="tpOtpHead"><div class="tpOtpBadge">Водитель</div><h2>На какой машине</h2><p>Без машины на линию нельзя. CRM запомнит выбор.</p></div>' +
        '<div class="tpVehList"></div>' +
        '<div class="tpOtpActions"><button type="button" class="tpOtpGhost" data-k="cancel">Отмена</button></div>' +
      "</div>"
    );
    const box = root.querySelector(".tpVehList");
    let picked = lastId && list.some((v) => v.id === lastId) ? lastId : "";
    const render = () => {
      box.innerHTML =
        list
          .map((v) => {
            const lab = (v.name || v.id) + (v.plate ? " · " + v.plate : "");
            return (
              '<button type="button" class="tpVehBtn' +
              (v.id === picked ? " on" : "") +
              '" data-id="' +
              __tpEsc(v.id) +
              '">' +
              __tpEsc(lab) +
              "</button>"
            );
          })
          .join("") +
        '<button type="button" class="tpOtpPrimary" data-k="ok"' +
        (picked ? "" : " disabled") +
        ">На линию</button>";
    };
    render();
    root.addEventListener("click", (ev) => {
      const btn = ev.target.closest("button");
      if (!btn) return;
      if (btn.getAttribute("data-k") === "cancel") {
        root.remove();
        resolve(null);
        return;
      }
      const id = btn.getAttribute("data-id");
      if (id) {
        picked = id;
        render();
        return;
      }
      if (btn.getAttribute("data-k") === "ok") {
        if (!picked) return;
        root.remove();
        resolve(picked);
      }
    });
  });
};

window.__tpAskDriverDone = function (order) {
  return new Promise((resolve) => {
    const base = order && order.revenue > 0 ? Math.round(order.revenue) : 0;
    const when = __tpNowMskLabel();
    const state = {
      loadingHard: false,
      noTowHook: false,
      jumpStart: false,
      rollersOn: false,
      rollersCount: 1,
    };
    const RUB = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    const extraSum = () => {
      let s = 0;
      if (state.loadingHard) s += 1500;
      if (state.noTowHook) s += 500;
      if (state.jumpStart) s += 3000;
      if (state.rollersOn) s += state.rollersCount * 1500;
      return s;
    };
    const extrasLabel = () => {
      const bits = [];
      if (state.loadingHard) bits.push("погрузка +1500");
      if (state.noTowHook) bits.push("крюк +500");
      if (state.jumpStart) bits.push("прикурить +3000");
      if (state.rollersOn) bits.push("подкаты ×" + state.rollersCount + " +" + state.rollersCount * 1500);
      return bits.length ? bits.join(" · ") : "Нет — нажмите, чтобы добавить";
    };

    const root = __tpOverlay(
      '<div class="tpOtpCard tpDoneCard" role="dialog" aria-modal="true">' +
        '<div class="tpOtpGlow"></div>' +
        '<div class="tpOtpHead">' +
        '<div class="tpOtpBadge">Водитель</div>' +
        "<h2>Завершить заказ</h2>" +
        "<p>Диспетчера нет на линии — закрываете сами. Время зафиксируется автоматически.</p>" +
        "</div>" +
        '<div class="tpOtpTime"><span>Время завершения</span><strong>' +
        __tpEsc(when) +
        "</strong></div>" +
        '<label class="tpOtpField"><span>Сумма заказа, ₽</span>' +
        '<input class="tpOtpInput" data-k="rev" inputmode="numeric" placeholder="Например 4500" value="' +
        __tpEsc(base || "") +
        '"></label>' +
        '<div class="tpOtpPay"><span>Оплата</span><div class="tpOtpPayRow">' +
        '<button type="button" data-pay="cash" class="on">Наличные</button>' +
        '<button type="button" data-pay="transfer">Перевод</button>' +
        '<button type="button" data-pay="cashless">Безнал</button></div></div>' +
        '<button type="button" class="tpExtrasOpen" data-act="extras">' +
        '<span class="tpExtrasOpen__ico">＋</span>' +
        '<span class="tpExtrasOpen__body">' +
        '<strong>Дополнительные услуги</strong>' +
        '<em data-k="exlabel">Нет — нажмите, чтобы добавить</em>' +
        "</span>" +
        '<span class="tpExtrasOpen__sum" data-k="exsum">+0 ₽</span>' +
        "</button>" +
        '<div class="tpDoneTotal">Сумма заказа: <strong data-k="total">0</strong> ₽</div>' +
        '<div class="tpOtpErr" hidden></div>' +
        '<div class="tpOtpActions tpDoneActions">' +
        '<button type="button" class="tpOtpGhost" data-act="cancel">Отмена</button>' +
        '<button type="button" class="tpOtpPrimary tpDoneOk" data-act="ok">Подтвердить</button>' +
        "</div></div>"
    );

    let pay = "cash";
    let extrasLayer = null;
    const err = root.querySelector(".tpOtpErr");
    const revInp = root.querySelector('[data-k="rev"]');
    const totalEl = root.querySelector('[data-k="total"]');
    const exLabel = root.querySelector('[data-k="exlabel"]');
    const exSumEl = root.querySelector('[data-k="exsum"]');

    const baseRev = () => {
      const raw = String(revInp.value || "").replace(/\s/g, "").replace(",", ".");
      const n = Number(raw);
      return Number.isFinite(n) && n > 0 ? Math.round(n) : 0;
    };
    const paint = () => {
      const add = extraSum();
      totalEl.textContent = RUB(baseRev());
      exLabel.textContent = extrasLabel();
      exSumEl.textContent = add > 0 ? "инфо, не в сумме" : "";
      root.querySelector(".tpExtrasOpen").classList.toggle("hasExtras", add > 0);
    };
    const close = (v) => {
      if (extrasLayer) {
        extrasLayer.remove();
        extrasLayer = null;
      }
      root.remove();
      resolve(v);
    };

    const openExtras = () => {
      if (extrasLayer) return;
      const layer = document.createElement("div");
      layer.className = "tpExtrasOverlay";
      layer.innerHTML =
        '<div class="tpExtrasCard" role="dialog" aria-modal="true">' +
        '<div class="tpExtrasCard__glow"></div>' +
        '<header class="tpExtrasCard__head">' +
        '<div class="tpExtrasCard__eyebrow">ДОПЫ К ЗАКАЗУ</div>' +
        "<h3>Дополнительные услуги</h3>" +
        "<p>Отметьте, что было на заказе. Галочки — что сделали. В сумму не входят.</p>" +
        '<button type="button" class="tpExtrasCard__close" data-ex-act="close" aria-label="Закрыть">✕</button>' +
        "</header>" +
        '<div class="tpExtrasList">' +
        '<label class="tpExItem"><input type="checkbox" data-ex="loadingHard"' +
        (state.loadingHard ? " checked" : "") +
        '><span class="tpExItem__txt"><strong>Сложность погрузки</strong><em>Труднодоступно / долго</em></span>' +
        '<span class="tpExItem__price">+1 500 ₽</span></label>' +
        '<label class="tpExItem"><input type="checkbox" data-ex="noTowHook"' +
        (state.noTowHook ? " checked" : "") +
        '><span class="tpExItem__txt"><strong>Нет буксировочного крюка</strong><em>Без штатной точки крепления</em></span>' +
        '<span class="tpExItem__price">+500 ₽</span></label>' +
        '<label class="tpExItem"><input type="checkbox" data-ex="jumpStart"' +
        (state.jumpStart ? " checked" : "") +
        '><span class="tpExItem__txt"><strong>Прикурить авто</strong><em>От 3000 ₽</em></span>' +
        '<span class="tpExItem__price">+3 000 ₽</span></label>' +
        '<div class="tpExItem tpExItem--roll">' +
        '<label class="tpExItem tpExItem--inline"><input type="checkbox" data-ex="rollers"' +
        (state.rollersOn ? " checked" : "") +
        '><span class="tpExItem__txt"><strong>Подкаты</strong><em>1 подкат = 1 500 ₽</em></span>' +
        '<span class="tpExItem__price">+1 500 ₽/шт</span></label>' +
        '<div class="tpExQtyWrap" data-qty ' +
        (state.rollersOn ? "" : "hidden") +
        ">" +
        '<div class="tpExQtyLabel">Сколько подкатов?</div>' +
        '<div class="tpExQty">' +
        [1, 2, 3, 4]
          .map(
            (n) =>
              '<button type="button" data-roll="' +
              n +
              '"' +
              (n === state.rollersCount ? ' class="on"' : "") +
              "><b>" +
              n +
              "</b><span>" +
              RUB(n * 1500) +
              " ₽</span></button>"
          )
          .join("") +
        "</div></div></div>" +
        "</div>" +
        '<div class="tpExtrasFooter">' +
        '<div class="tpExtrasFooter__sum">Допы: <strong data-k="exfoot">0</strong> ₽</div>' +
        '<button type="button" class="tpExtrasApply" data-ex-act="apply">Готово</button>' +
        "</div></div>";
      document.body.appendChild(layer);
      extrasLayer = layer;
      requestAnimationFrame(() => layer.classList.add("on"));

      const qtyWrap = layer.querySelector("[data-qty]");
      const foot = layer.querySelector('[data-k="exfoot"]');
      const syncFoot = () => {
        foot.textContent = RUB(extraSum());
      };
      const readChecks = () => {
        state.loadingHard = !!layer.querySelector('[data-ex="loadingHard"]').checked;
        state.noTowHook = !!layer.querySelector('[data-ex="noTowHook"]').checked;
        state.jumpStart = !!layer.querySelector('[data-ex="jumpStart"]').checked;
        state.rollersOn = !!layer.querySelector('[data-ex="rollers"]').checked;
        qtyWrap.hidden = !state.rollersOn;
        if (!state.rollersOn) {
          /* keep last count but not billed */
        } else if (!state.rollersCount) {
          state.rollersCount = 1;
        }
        syncFoot();
      };

      layer.querySelectorAll('[data-ex="loadingHard"],[data-ex="noTowHook"],[data-ex="jumpStart"],[data-ex="rollers"]').forEach((el) =>
        el.addEventListener("change", readChecks)
      );
      layer.querySelectorAll("[data-roll]").forEach((btn) =>
        btn.addEventListener("click", () => {
          state.rollersCount = Number(btn.getAttribute("data-roll")) || 1;
          layer.querySelectorAll("[data-roll]").forEach((b) => b.classList.toggle("on", b === btn));
          syncFoot();
        })
      );
      const dismiss = () => {
        layer.classList.remove("on");
        setTimeout(() => {
          if (extrasLayer === layer) {
            layer.remove();
            extrasLayer = null;
          }
        }, 180);
        paint();
      };
      layer.addEventListener("click", (e) => {
        if (e.target === layer) dismiss();
      });
      layer.querySelector('[data-ex-act="close"]').onclick = dismiss;
      layer.querySelector('[data-ex-act="apply"]').onclick = () => {
        readChecks();
        dismiss();
      };
      syncFoot();
    };

    root.addEventListener("click", (e) => {
      if (e.target === root) close(null);
    });
    root.querySelectorAll("[data-pay]").forEach((btn) =>
      btn.addEventListener("click", () => {
        pay = btn.getAttribute("data-pay");
        root.querySelectorAll("[data-pay]").forEach((b) => b.classList.toggle("on", b === btn));
      })
    );
    revInp.addEventListener("input", paint);
    root.querySelector('[data-act="cancel"]').onclick = () => close(null);
    root.querySelector('[data-act="extras"]').onclick = () => openExtras();
    root.querySelector('[data-act="ok"]').onclick = () => {
      const rev = baseRev();
      if (!rev) {
        err.hidden = false;
        err.textContent = "Укажите сумму заказа";
        return;
      }
      const extras = {
        loadingHard: !!state.loadingHard,
        noTowHook: !!state.noTowHook,
        jumpStart: !!state.jumpStart,
        rollersCount: state.rollersOn ? state.rollersCount : 0,
      };
      const add = extraSum();
      close({
        revenue: rev,
        paymentMethod: pay,
        completedAt: __tpNowIsoMsk(),
        extras,
      });
    };
    paint();
    setTimeout(() => revInp && revInp.focus(), 50);
  });
};
