    const inpPct=blkPct.querySelector("input");inpPct.value=pct0?String(pct0):"30";if(isOrgLead)inpPct.readOnly=!0;
    const blkAmt=tpPrEl("label","odoKm prBlock");
    blkAmt.innerHTML=(isOrgLead?"Им ₽ *":"Наш доход ₽ *")+'<input inputmode="decimal" placeholder="Авто из %">';
    const inpAmt=blkAmt.querySelector("input");inpAmt.value=share0?String(Math.round(share0)):"";
