  if(old)old.remove();
  const overlay=tpPrEl("div","odoOverlay prAlarmOverlay");
  overlay.setAttribute("role","alertdialog");
  overlay.setAttribute("aria-modal","true");
  const sheet=tpPrEl("div","odoSheet prAlarmSheet");
  const nums=list.slice(0,8).map(o=>"#"+String(o.id||"").slice(0,8)).join(", ");
  const more=list.length>8?(" и ещё "+(list.length-8)) : "";
  sheet.innerHTML='<header class="odoHead"><div><strong>Будильник · партнёр не закрыт</strong><p>Прошёл час, а заявка всё ещё открыта. Закройте через «Выплачено».</p></div></header>';
  const body=tpPrEl("div","prAlarmBody");
  body.textContent=(list.length===1?"Заказ "+nums:("Заказы: "+nums))+more;
  const foot=tpPrEl("div","odoFoot");
  const ok=tpPrEl("button","odoBtn confirm");ok.type="button";ok.textContent="Понятно";
  ok.addEventListener("click",()=>overlay.remove());
  foot.append(ok);
  sheet.append(body,foot);
  overlay.append(sheet);
