      const res=await un("/api/fuel-receipts",{method:"POST",body:JSON.stringify({driverName:driver,vehicleId:ctx.vehicleId||"",vehicleLabel:ctx.vehicleLabel||"",date:form.elements.date.value,period:ctx.period||"day",kind,amount,litres:kind==="fuel"?litres:null,paySource:form.elements.paySource?form.elements.paySource.value:"revenue",note:noteOut,photo:photoData,createdBy:driver})},void 0,6e4);
      const data=await res.json().catch(()=>({}));
